+	err = amdgpu_amdkfd_gpuvm_export_dmabuf(mem->mem, &dmabuf);
+	if (err) {
+		pr_debug("export dmabuf failed\n");
+		return -ENOMEM;
+	}
+
+	dma_buf_put(dmabuf);
+
+	return 0;
+}
