@@ -1563,11 +1605,46 @@ static int pxa2xx_spi_resume(struct device *dev)
 	/* Enable the SSP clock */
 	status = pxa2xx_spi_clk_enable(drv_data);
 	if (status)
-		return status;
+		goto out_put;
 
-	if (is_lpss_ssp(drv_data))
